from pathlib import Path
import json,re,sys

CID="AUTO-DISCOVERY-54d13314c7879b58e46d"
MODEL_TASK="A2Z-V4-ASTRA-POSTBUILD-20261006-R3-P2"
roots=[
 Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4",
 Path.home()/".local/share/prediction-project-executor/worktrees/DEV-PRED-A2Z-POSTBUILD-RETRY-20261006-E106",
 Path.home()/".local/state/prediction-codex-supervisor",
]
records=[]
def walk(o,path):
 if isinstance(o,dict):
  dec=str(o.get("decision","")).upper()
  blob=json.dumps(o,sort_keys=True,default=str)
  if dec in {"APPROVE","NEEDS_REVISION","REVISE","REJECT","PARK"} and (CID in blob or MODEL_TASK in blob or "POSTBUILD" in blob.upper() or "postbuild" in path.lower()):
   records.append((path,o))
  for v in o.values(): walk(v,path)
 elif isinstance(o,list):
  for v in o: walk(v,path)
for root in roots:
 if not root.exists(): continue
 for p in root.rglob("*"):
  try:
   if not p.is_file() or p.stat().st_size>2000000: continue
  except OSError: continue
  if p.suffix.lower() not in {".json",".jsonl"}: continue
  try: raw=p.read_text(errors="replace")
  except Exception: continue
  low=raw.lower()
  if CID.lower() not in low and MODEL_TASK.lower() not in low and "postbuild" not in low: continue
  if p.suffix.lower()==".json":
   try: walk(json.loads(raw),str(p))
   except Exception: pass
  else:
   for line in raw.splitlines():
    try: walk(json.loads(line),str(p))
    except Exception: pass
uniq=[]; seen=set()
for path,d in records:
 key=(path,json.dumps(d,sort_keys=True,default=str))
 if key in seen: continue
 seen.add(key); uniq.append((path,d))
def first(d,names):
 for n in names:
  if d.get(n) not in (None,""): return d.get(n)
 return None
approvals=[]; revisions=[]; rejects=[]
for path,d in uniq:
 dec=str(d.get("decision","")).upper()
 rec={
  "phase":first(d,["phase","review_phase","gate","review_kind"]),
  "model":first(d,["reviewer_model","model","model_display_name"]),
  "slug":first(d,["reviewer_model_slug","model_slug","selected_slug"]),
  "binding":first(d,["binding_sha256","review_binding_sha256","build_binding_sha256","binding_hash","binding"]),
  "provref":first(d,["model_provenance_ref","provenance_ref"]),
  "provsha":first(d,["model_provenance_sha256","provenance_sha256"]),
  "candidate":d.get("candidate_id")
 }
 if dec=="APPROVE": approvals.append(rec)
 elif dec in {"NEEDS_REVISION","REVISE"}: revisions.append(rec)
 elif dec in {"REJECT","PARK"}: rejects.append(rec)
exact=[r for r in approvals if str(r["phase"]).upper()=="POSTBUILD" and r["model"]=="GPT-6 Astra" and r["slug"]=="gpt-6-astra" and isinstance(r["binding"],str) and re.fullmatch(r"[0-9a-f]{64}",r["binding"]) and r["provref"] and isinstance(r["provsha"],str) and re.fullmatch(r"[0-9a-f]{64}",r["provsha"]) and r["candidate"] in (None,CID)]
if exact: print("E111=EXACT_POSTBUILD_APPROVE_FIELDS_PRESENT",flush=True); raise SystemExit(0)
if revisions: print("E111=NEEDS_REVISION_RECORD_PRESENT",flush=True); raise SystemExit(20)
if rejects: print("E111=REJECT_OR_PARK_RECORD_PRESENT",flush=True); raise SystemExit(21)
if not approvals: print("E111=NO_APPROVE_RECORD",flush=True); raise SystemExit(22)
checks=[
 ("POSTBUILD_PHASE",lambda r:str(r["phase"]).upper()=="POSTBUILD",31),
 ("EXACT_MODEL_NAME",lambda r:r["model"]=="GPT-6 Astra",32),
 ("EXACT_MODEL_SLUG",lambda r:r["slug"]=="gpt-6-astra",33),
 ("BINDING_64HEX",lambda r:isinstance(r["binding"],str) and re.fullmatch(r"[0-9a-f]{64}",r["binding"]),34),
 ("PROVENANCE_REF",lambda r:bool(r["provref"]),35),
 ("PROVENANCE_SHA_64HEX",lambda r:isinstance(r["provsha"],str) and re.fullmatch(r"[0-9a-f]{64}",r["provsha"]),36),
]
for label,pred,rc in checks:
 if not any(pred(r) for r in approvals):
  print("E111=MISSING_"+label,flush=True); raise SystemExit(rc)
print("E111=FIELDS_SPLIT_OR_NOT_SINGLE_BOUND_RECORD",flush=True); raise SystemExit(37)
